// EAR OS · Normalización del mensaje entrante de WhatsApp Cloud API.
// Acepta texto y NOTA DE VOZ (audio): en ese caso adjunta el mediaId para que
// el canal oficial resuelva la transcripción. Nunca inventa contenido: si el
// payload no trae un campo reconocible, marca handled=false y escala a humano.
const entry = ($input.first().json.body?.entry ?? $input.first().json.entry ?? [])[0];
const change = entry?.changes?.[0]?.value ?? {};
const message = change.messages?.[0] ?? null;
if (!message) {
  return { handled: false, reason: 'sin_mensaje', escalate: false };
}
const text = message.text?.body ?? '';
const audioId = message.audio?.id ?? message.voice?.id ?? null;
const q = String(text).toLowerCase();
const intent = /(como llego|c[oó]mo llego|llegar|direcci[oó]n|acceso|parking|p[aá]rking|mapa|gps)/.test(q)
  ? 'directions'
  : /(men[uú]|precio|cu[aá]nto cuesta|banquete|carta)/.test(q)
    ? 'menus'
    : /(aforo|capacidad|invitados|jard[ií]n|sal[oó]n)/.test(q)
      ? 'capacity'
      : /(reserv|bloque|fianza|dep[oó]sito|se[nñ]al)/.test(q)
        ? 'booking'
        : 'general';
return {
  handled: true,
  from: message.from ?? null,
  type: message.type ?? 'unknown',
  text,
  audioId,
  isVoiceNote: Boolean(audioId),
  intent,
  escalate: false,
  receivedAt: new Date().toISOString()
};
